719	fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
720	    let value = read_json_file(path)?;
721	    // A stale intent is the expected failure after a schema bump; name it
722	    // before serde reports it as an opaque parse error.
723	    let found = &value["schemaVersion"];
724	    if found != &serde_json::json!(ReleaseIntentV1::SCHEMA_VERSION) {
725	        return Err(CliError::ReleaseIntentSchemaUnsupported {
726	            path: path.to_path_buf(),
727	            found: found.to_string(),
728	            expected: ReleaseIntentV1::SCHEMA_VERSION,
729	        });
730	    }
731	    let wire: ReleaseIntentV1Wire = serde_json::from_value(value).map_err(|error| CliError::ReleaseIntentInvalid {
732	        path: path.display().to_string(),
733	        detail: error.to_string(),
734	    })?;
735	    Ok(ReleaseIntentV1::from_wire(wire)?)
736	}
