380	/// the kind of duplicated logic that drifts: an earlier version of this
381	/// function did just that, understood only a direct changeset match, and
382	/// rejected every real release in this repository once a fixed-group cascade
383	/// (a case its reimplementation never learned) touched an unnamed sibling.
384	///
385	/// Instead, this function reads the committed decision back and confirms the
386	/// commit's actual diff matches it exactly -- no more, no less.
387	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
388	/// entries don't match its content digest, so a hand-edited or corrupted
389	/// decision file fails before this function's own diff cross-check runs.
390	///
391	/// The caller must check out the exact merge commit in detached HEAD state
392	/// before creating an intent. GitHub-specific PR/approval provenance belongs
393	/// in the workflow boundary; this graph function verifies the local,
394	/// provider-neutral commit delta only.
395	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
396	    workspace: &Workspace<'_, R, D>,
397	    release_commit: &CommitSha,
398	    decision_path: &std::path::Path,
399	) -> Result<ReleaseDecisionV1, GraphError> {
400	    let (parent, changed) = commit_delta(workspace, release_commit)?;
401	    let decision_path_str = normalized_git_path(decision_path)?;
402	    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
403	    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
404	    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
405	    Ok(decision)
406	}
