124	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
125	        if entries.is_empty() {
126	            return Err(ReleaseDecisionError::EmptyRoster);
127	        }
128	        for entry in &mut entries {
129	            entry.reasons.sort();
130	            entry.reasons.dedup();
131	            if entry.reasons.is_empty() {
132	                return Err(ReleaseDecisionError::MissingReason {
133	                    package: entry.package.clone(),
134	                });
135	            }
136	        }
137	        entries.sort_by(|left, right| left.package.cmp(&right.package));
138	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
139	            return Err(ReleaseDecisionError::DuplicatePackage);
140	        }
141	
142	        // A fixed or linked group always converges every member to one
143	        // shared target version -- `solve_cascade` guarantees this when a
144	        // decision is derived from a version plan. Entries tag their own
145	        // group membership via `FixedGroup`/`LinkedGroup` reasons, so this
146	        // invariant is checkable from the decision's own content alone, with
147	        // no `GroupTable`/workspace-config access needed. Rejecting a
148	        // violation here means it also applies to a decision deserialized
149	        // from a committed release-decision file (`Deserialize` calls
150	        // `new()`), not just one freshly derived from a plan.
151	        let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
152	        for entry in &entries {
153	            for reason in &entry.reasons {
154	                let group_id = match reason {
155	                    ReleaseInclusionReason::FixedGroup { group_id }
156	                    | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
157	                    _ => continue,
158	                };
159	                match group_targets.get(group_id) {
160	                    Some(existing) if **existing != entry.target_version => {
161	                        return Err(ReleaseDecisionError::DivergentGroupTarget {
162	                            group_id: group_id.to_string(),
163	                            left: (*existing).clone(),
164	                            right: entry.target_version.clone(),
165	                        });
166	                    }
167	                    _ => {
168	                        group_targets.insert(group_id, &entry.target_version);
169	                    }
170	                }
171	            }
172	        }
