486	/// Replaces each publish leaf with prerequisites from selected dependency packages.
487	fn link_publish_prerequisites<R: CommandRunner, D: DependencyResolver>(
488	    workspace: &Workspace<'_, R, D>,
489	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
490	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
491	    publish_edges: &PublishEdgeFilter,
492	    ops: &mut Ops,
493	) -> Result<(), GraphError> {
494	    let Ops {
495	        operations,
496	        index: OpIndex {
497	            publishes_by_package,
498	            platforms_by_publish,
499	            ..
500	        },
501	        ..
502	    } = ops;
503	
504	    // Replace each publish leaf with prerequisites from selected dependency
505	    // packages, ordered by the shared publish edge filter.
506	    for (id, (package, _)) in selected {
507	        let mut prerequisites = BTreeSet::new();
508	        for edge in workspace.graph.dependencies_of(&package.id) {
509	            if !publish_edges.allows(&package.id, &edge.to, edge.kind) {
510	                continue;
511	            }
512	            // The edge names the dependency's distribution in the declaring manifest's ecosystem, so a Cargo
513	            // dependent waits for the dependency's crate, not for its npm package. No such distribution means the
514	            // edge was resolved some other way, so it waits for all of them.
515	            let ecosystem = crate::cascade::manifest_ecosystem(&edge.from_manifest);
516	            let dependency_ids = package_ids.get(&edge.to).map(Vec::as_slice).unwrap_or_default();
517	            let touched: Vec<&ReleasePackageId> = dependency_ids
518	                .iter()
519	                .filter(|dependency_release_id| dependency_release_id.ecosystem() == ecosystem)
520	                .collect();
521	            let dependency_ids: Vec<&ReleasePackageId> = if touched.is_empty() {
522	                dependency_ids.iter().collect()
523	            } else {
524	                touched
525	            };
526	            for dependency_release_id in dependency_ids {
527	                prerequisites.extend(
528	                    publishes_by_package
529	                        .get(dependency_release_id)
530	                        .into_iter()
531	                        .flatten()
532	                        .cloned(),
533	                );
534	            }
535	        }
536	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
537	            let operation = operations.get(publish_id).expect("publish operation was constructed");
538	            let mut prerequisites = prerequisites.clone();
539	            prerequisites.extend(platforms_by_publish.get(publish_id).into_iter().flatten().cloned());
540	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.into_iter().collect())?;
541	            operations.insert(publish_id.clone(), replacement);
542	        }
543	    }
544	    Ok(())
545	}
