677	/// The artifact slots and their upload operations, with the uploads each product package's forge publish waits on.
678	fn add_artifact_uploads<R: CommandRunner, D: DependencyResolver>(
679	    workspace: &Workspace<'_, R, D>,
680	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
681	    owners: &Owners,
682	    artifact_policy: Option<&ArtifactBuildPolicy>,
683	    ops: &mut Ops,
684	    diagnostics: &mut Vec<Diagnostic>,
685	) -> Result<Vec<ArtifactSlotId>, GraphError> {
686	    let Ops {
687	        operations,
688	        prepared,
689	        index:
690	            OpIndex {
691	                tag_by_package,
692	                forge_by_package,
693	                uploads_by_package,
694	                asset_owner_tags_by_package,
695	                ..
696	            },
697	    } = ops;
698	
699	    let mut artifact_slots = Vec::new();
700	    if let (Some(product), Some(policy)) = (&workspace.config.product_release, artifact_policy) {
701	        require_product_package_publishes_to_forge(workspace, &product.package)?;
702	        // Resolved through IdentityIndex, not `PackageId::matches`: a Bare
703	        // package id is not an ecosystem wildcard here -- a same-name
704	        // package in another ecosystem must never match the product/artifact selector.
705	        let matches_product =
706	            |package: &callisto_model::Package| workspace.identity.identifies(&product.package, &package.id);
707	        if !selected.values().any(|(package, _)| matches_product(package)) {
708	            // The product isn't in this release, so warn instead of leaving the artifact owner's asset unregistered.
709	            for artifact in &product.artifacts {
710	                if let Some((owner_id, _)) = owned(selected, owners)
711	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
712	                {
713	                    diagnostics.push(unreleased_product_artifact_diagnostic(
714	                        &product.package,
715	                        artifact,
716	                        owner_id,
717	                    ));
718	                }
719	            }
720	        }
721	        for (id, (package, _)) in owned(selected, owners) {
722	            if !matches_product(package) {
723	                continue;
724	            }
725	            let forge = forge_by_package.get(id).ok_or_else(|| GraphError::ReleaseInvariant {
726	                detail: format!("product package `{id}` has no forge release operation"),
727	            })?;
728	            let (tag, prerelease) = match prepared.get(forge) {
729	                Some(PreparedOperation::ForgeRelease(prepared_forge)) => {
730	                    (prepared_forge.tag.clone(), prepared_forge.prerelease)
731	                }
732	                _ => {
733	                    return Err(GraphError::ReleaseInvariant {
734	                        detail: format!("product forge release `{forge:?}` is not prepared"),
735	                    })
736	                }
737	            };
738	            for artifact in &product.artifacts {
739	                // The slot names the package whose build produced the bytes, which
740	                // need not be the product -- a plugin can ship on the product's
741	                // release. Every slot still attaches to the product's one release.
742	                let (owner_id, owner_version) = owned(selected, owners)
743	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
744	                    .map(|(candidate, (_, owner_version))| (candidate.clone(), owner_version.clone()))
745	                    .ok_or_else(|| GraphError::ReleaseArtifactOwnerNotReleased {
746	                        asset: artifact.asset_name.clone(),
747	                        package: artifact.package.to_string(),
748	                    })?;
749	                let slot = ArtifactSlotId::new(
750	                    owner_id.clone(),
751	                    owner_version.clone(),
752	                    &artifact.target,
753	                    artifact.asset_name.clone(),
754	                    policy.repository.clone(),
755	                    policy.workflow_path.clone(),
756	                    policy.workflow_commit.clone(),
757	                )
758	                .map_err(|error| GraphError::ReleaseInvariant {
759	                    detail: format!("invalid configured artifact slot: {error}"),
760	                })?;
761	                let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![forge.clone()])?;
762	                prepared.insert(
763	                    operation.id().clone(),
764	                    PreparedOperation::ArtifactUpload(ArtifactUploadOperation {
765	                        slot: slot.clone(),
766	                        tag: tag.clone(),
767	                        prerelease,
768	                    }),
769	                );
770	                // Keyed by the product's id: a plugin-built asset must still gate the product's own forge-publish.
771	                uploads_by_package
772	                    .entry(id.clone())
773	                    .or_default()
774	                    .push(operation.id().clone());
775	                if owner_id != *id
776	                    && let Some(owner_tag) = tag_by_package.get(&owner_id)
777	                {
778	                    asset_owner_tags_by_package
779	                        .entry(id.clone())
780	                        .or_default()
781	                        .insert(owner_tag.clone());
782	                }
783	                operations.insert(operation.id().clone(), operation);
784	                artifact_slots.push(slot);
785	            }
786	        }
787	    }
788	    Ok(artifact_slots)
789	}
