791	fn add_forge_publishes(
792	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
793	    owners: &Owners,
794	    ops: &mut Ops,
795	) -> Result<(), GraphError> {
796	    let Ops {
797	        operations,
798	        prepared,
799	        index:
800	            OpIndex {
801	                forge_by_package,
802	                uploads_by_package,
803	                asset_owner_tags_by_package,
804	                ..
805	            },
806	    } = ops;
807	
808	    // Publishing is the last forge step: a GitHub Release is only complete
809	    // once every asset it carries has been uploaded to it as a draft.
810	    for (id, (_, version)) in owned(selected, owners) {
811	        let Some(forge) = forge_by_package.get(id) else {
812	            continue;
813	        };
814	        let mut prerequisites = vec![forge.clone()];
815	        prerequisites.extend(uploads_by_package.get(id).into_iter().flatten().cloned());
816	        prerequisites.extend(asset_owner_tags_by_package.get(id).into_iter().flatten().cloned());
817	        let operation = ReleaseOperation::forge_publish(id.clone(), version.clone(), prerequisites)?;
818	        let tag = match prepared.get(forge) {
819	            Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
820	            _ => {
821	                return Err(GraphError::ReleaseInvariant {
822	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
823	                })
824	            }
825	        };
826	        prepared.insert(
827	            operation.id().clone(),
828	            PreparedOperation::ForgePublish(ForgePublishOperation {
829	                tag,
830	                prerelease: version.is_prerelease(),
831	            }),
832	        );
833	        operations.insert(operation.id().clone(), operation);
834	    }
835	    Ok(())
836	}
